# פרק 5 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=5
TITLE='התקדים המחייב והלכת בית המשפט'
SUM=[' <p>אחד ממאפייני המשפט הישראלי כשיטה מעורבת — מעמדו של ה<strong>תקדים</strong> (Stare Decisis).</p> <h3>5.1 הכלל — סעיף 20 לחוק יסוד: השפיטה</h3> <p>הלכה שנפסקה ב<strong>בית המשפט העליון</strong> <strong>מחייבת</strong> כל ערכאה נמוכה ממנו. <strong>העליון עצמו אינו כבול</strong> להלכותיו, ורשאי לסטות מהן (אך עושה זאת בריסון).</p> <h3>5.2 רציו מול אמרת אגב</h3> <p>מחייב רק ה<strong>"רציו דצידנדי"</strong> — הנימוק המשפטי שהיה <strong>חיוני להכרעה</strong>; <strong>"אמרת אגב" (אוביטר)</strong> — הערה שאינה חיונית — אינה מחייבת, אך עשויה להנחות.</p> <h3>5.3 ההבחנה ("הבחנה")</h3> <p>ערכאה רשאית <strong>להבחין</strong> את המקרה שלפניה מהתקדים אם עובדותיו המהותיות שונות — כלי לפיתוח הדרגתי של ההלכה.</p> <h3>5.4 נקודות מפתח למבחן</h3> <ul><li>תקדים העליון מחייב ערכאות נמוכות (ס׳ 20); העליון לא כבול.</li><li>רציו (מחייב) מול אוביטר (מנחה).</li><li>הבחנה — בידול מהתקדים לפי עובדות.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('ע״א 4628/93 מדינת ישראל נ׳ אפרופים שיכון וייזום (1991) בע״מ', 'מחלוקת חוזית בין המדינה לחברה קבלנית בשאלה כיצד מפרשים חוזה (1995).', 'הנשיא ברק קבע שחוזה מתפרש בתהליך חד־שלבי, שבו נבחנים יחד לשון החוזה והנסיבות החיצוניות כדי לברר את אומד דעת הצדדים. ההלכה חייבה את כל הערכאות, אושררה בדיון נוסף (ארגון מגדלי ירקות), ועוררה תגובת חקיקה ב־2011 ושוב ב־2026. זו דוגמה מרכזית לכוחה של הלכה פסוקה ולדיאלוג בין בית המשפט לכנסת.'), ('רע״א 3961/10 המוסד לביטוח לאומי נ׳ סהר חברה לתביעות בע״מ', 'אחרי שהכנסת תיקנה ב־2011 את ס׳ 25(א) לחוק החוזים כדי לשנות את הלכת אפרופים, נדרש העליון לפרש את התיקון (2012).', 'דעת הרוב קבעה שהתיקון הוא למעשה אימוץ של הגישה הפרשנית של אפרופים, תוך הדגשת מקומה החשוב של לשון החוזה. השופט הנדל סבר בדעת מיעוט שהתיקון נועד לשנות את המצב. הפרשה מראה שגם כשהמחוקק מגיב להלכה, הפרשנות של החוק החדש נשארת בידי בית המשפט.'), ('ע״א 7649/18 ביבי כבישים עפר ופיתוח בע״מ נ׳ רכבת ישראל בע״מ', 'ערעור בעניין חוזי שבמסגרתו התייחס השופט שטיין להלכת אפרופים ולתיקון לחוק החוזים (2019).', 'השופט שטיין כתב, בהערת אגב, שהלכת אפרופים חלה על כל חוזה, אבל "לא כל החוזים נולדו שווים", והבחין בין חוזי יחס, שבהם השופט משלים תנאים לפי עקרונות כמו תום לב, לבין חוזים סגורים וממצים, שאינם זקוקים לפרשנות יצירתית. ההערה אינה הלכה מחייבת, אך זכתה למשקל משכנע ולהתייחסות רבה.'), ('ע״פ 5121/98 יששכרוב נ׳ התובע הצבאי הראשי', 'חייל נחקר בחשד לשימוש בסם ומסר הודאה מפורטת, ורק בתום החקירה נאמר לו שזכותו להיוועץ בעורך דין.', 'העליון (השופטת ביניש) אימץ לראשונה דוקטרינת פסילה פסיקתית לראיות שהושגו שלא כדין, בהשראת חוק־יסוד: כבוד האדם וחירותו, ופסל את ההודאה. הדוקטרינה אינה כתובה בחוק — מקורה בהלכה, והיא מחייבת מאז את כל הערכאות. זו דוגמה להלכה פסוקה כמקור משפט יוצר.'), ('רע״פ 10141/09 בן חיים נ׳ מדינת ישראל', 'השאלה הייתה מתי חיפוש משטרתי שנעשה בהסכמת החשוד, בלי חשד סביר, הוא חוקי (2012).', 'נקבע שהסכמה מכשירה חיפוש כזה רק אם היא הסכמה מדעת, והסכמה כזו מתגבשת רק אחרי שהשוטר הבהיר שמותר לסרב ושלא יאונה רע למסרב. "הלכת בן חיים" חייבה מאז את הערכאות הנמוכות ואת רשויות האכיפה.'), ('דנג״ץ 5026/16 גיני נ׳ הרבנות הראשית לישראל', 'בעלי מסעדות ביקשו להציג את עסקיהם ככשרים בלי תעודת הכשר של הרבנות; אחרי שבג״ץ דחה את העתירה ב־2016 התקיים דיון נוסף (2017).', 'בדיון הנוסף נקבע שבית אוכל בלי תעודת הכשר לא יציג עצמו ככשר, אבל רשאי להציג מצג אמת על הסטנדרטים שהוא מקפיד עליהם ועל אופן הפיקוח, ובלבד שיבהיר במפורש שאין לו תעודת הכשר. הפרשה ממחישה את תפקיד הדיון הנוסף בגיבוש הלכה בשאלה בעלת חשיבות ציבורית.')]
QS=[{'q': 'לפי ס׳ 20 לחוק־יסוד: השפיטה, מה מעמדה של הלכה שנפסקה בבית משפט מחוזי כלפי בית משפט שלום?', 'o': ['היא מחייבת אותו רק אם ניתנה בהרכב של שלושה', 'אין לה כל מעמד כלפיו', 'היא מנחה אותו', 'היא מחייבת אותו באופן מוחלט'], 'c': 2, 'e': 'נכון. ס׳ 20(א): "הלכה שנפסקה בבית משפט תנחה בית משפט של דרגה נמוכה ממנו".'}, {'q': 'מה קובע ס׳ 20(ב) לחוק־יסוד: השפיטה?', 'o': ['הלכה שנפסקה בבית המשפט העליון מחייבת כל בית משפט, זולת בית המשפט העליון', 'הלכה שנפסקה בבית המשפט העליון מחייבת כל בית משפט, לרבות בית המשפט העליון', 'הלכה שנפסקה בבית המשפט העליון מנחה את בתי המשפט המחוזיים בלבד', 'הלכה שנפסקה בבית המשפט העליון מחייבת רק אם ניתנה בהרכב מורחב'], 'c': 0, 'e': 'נכון. זה נוסח הסעיף, והוא מעגן תקדים אנכי מחייב ושולל תקדים אופקי מחייב בעליון.'}, {'q': 'בית משפט מחוזי בחיפה פסק לפני שנה בשאלה מסוימת. כעת אותה שאלה מתעוררת בבית המשפט המחוזי בתל אביב, והעליון טרם הכריע. מה הדין?', 'o': ['המחוזי בתל אביב חייב לפסוק כמו חיפה לפי ס׳ 20(א)', 'המחוזי בתל אביב חייב להעביר את השאלה לעליון', 'המחוזי בתל אביב חייב לפסוק כמו חיפה, אלא אם נשיא העליון התיר אחרת', 'המחוזי בתל אביב אינו כבול לפסיקת המחוזי בחיפה, אך רשאי להתחשב בה כטיעון משכנע'], 'c': 3, 'e': 'נכון. אין תקדים אופקי מחייב; ס׳ 20(א) חל רק על ערכאה "נמוכה ממנו".'}, {'q': 'שופט מחוזי משוכנע שהלכה של העליון שגויה, ושאפשר להחיל אותה ישירות על התיק שלפניו. מה רשאי השופט לעשות?', 'o': ['לסטות ממנה, אם ינמק היטב', 'להורות על דיון נוסף בעליון', 'לפסוק לפי ההלכה, ותוך כך להביע ביקורת ולקרוא לבחינתה מחדש', 'להשהות את התיק עד שהכנסת תתקן את החוק'], 'c': 2, 'e': 'נכון. החובה היא לציית; מותר להביע ביקורת ולקרוא לעיון מחדש, וכך נוצר לחץ לשינוי ההלכה.'}, {'q': 'מהי "אבחנה" (distinguishing)?', 'o': ['הוכחה שהעובדות המהותיות בתיק החדש שונות, ולכן ההלכה אינה חלה עליו', 'סטייה גלויה מהלכה מחייבת', 'ביטול הלכה בחקיקה', 'החלטה לקיים דיון נוסף'], 'c': 0, 'e': 'נכון. אבחנה נשענת על שוני מהותי בעובדות; אבחנה מלאכותית שנועדה לעקוף הלכה היא בפועל סטייה אסורה.'}, {'q': 'בפסק דין של העליון נקבע שהנתבע חב בנזיקין משום שהתרשל. בהערה כתב השופט שאילו היה הנתבע רשות ציבורית, ייתכן שהדין היה שונה. הנתבע אינו רשות ציבורית. מה מעמד ההערה?', 'o': ['זו אמרת אגב — אינה מחייבת, אך יש לה משקל משכנע', 'זו דעת מיעוט', 'זו הלכה מחייבת', 'זו הוראה מחייבת לרשויות ציבוריות בלבד'], 'c': 0, 'e': 'נכון. ההערה עוסקת במקרה שלא היה לפני בית המשפט — אמרת אגב, שאינה מחייבת לפי ס׳ 20(ב) אך נשקלת כטיעון משכנע.'}, {'q': 'בפסק דין של חמישה שופטים בעליון: שניים קבעו שעילה קיימת בכל מקרה מסוג מסוים; שניים קבעו שהיא קיימת רק בחלק מהמקרים; אחד שלל אותה לגמרי. בית משפט שלום דן במקרה מאותו סוג. מה אסור לו לעשות?', 'o': ['לאמץ את גישת השניים הראשונים', 'לאמץ את גישת השניים האחרים ולבדוק אם המקרה מתאים', 'לקבוע שבשום מקרה אין עילה כזו', 'לבחון את המקרה לגופו לפי אחת מגישות הרוב'], 'c': 2, 'e': 'נכון. זה לקח פרשת זייצוב: המכנה המשותף של ארבעת שופטי הרוב הוא שהעילה אפשרית, ולכן אסור לקבוע שלעולם אין עילה.'}, {'q': 'על איזה פסק דין ניתן לבקש דיון נוסף לפי ס׳ 30 לחוק בתי המשפט?', 'o': ['על פסק דין של בית משפט מחוזי שישב בשלושה', 'על פסק דין של בית משפט שלום שאושר במחוזי', 'על כל פסק דין של בית המשפט העליון, בכל הרכב', 'על פסק דין של בית המשפט העליון שניתן בהרכב של שלושה'], 'c': 3, 'e': 'נכון. ס׳ 30(א)–(ב) וס׳ 18 לחוק היסוד: עניין שפסק בו העליון בשלושה; הדיון הנוסף — בחמישה או יותר.'}, {'q': 'מהן העילות לקיום דיון נוסף לפי ס׳ 30(ב) לחוק בתי המשפט?', 'o': ['סתירה להלכה קודמת של העליון, או חשיבות, קשיות או חידוש של ההלכה שנפסקה', 'גילוי ראיה חדשה שלא הייתה ידועה בזמן המשפט', 'טעות בקביעת עובדות או בהערכת מהימנות עדים', 'חשש לעיוות דין שנגרם לנידון'], 'c': 0, 'e': 'נכון. אלה שתי העילות שבסעיף: סתירה להלכה קודמת, או חשיבות, קשיותה או חידושה של ההלכה.'}, {'q': 'בעל דין הפסיד בעליון בהרכב של שלושה. לטענתו, השופטים טעו ביישום הלכה ידועה וברורה על העובדות שלו. הוא מבקש דיון נוסף. מה הסיכוי?', 'o': ['גבוה — כל טעות של העליון מצדיקה דיון נוסף', 'נמוך — אין כאן הלכה חדשה, חשובה, קשה או סותרת, אלא טענה לטעות ביישום', 'הבקשה תועבר למשפט חוזר', 'הבקשה תתקבל אוטומטית אם הוגשה במועד'], 'c': 1, 'e': 'נכון. תנאי סף לדיון נוסף הוא קיומה של הלכה שעומדת באחת העילות; טענה לטעות ביישום אינה כזו, ובקשות מתקבלות לעתים נדירות.'}, {'q': 'מה מלמדת פרשת נחמני על מוסד הדיון הנוסף?', 'o': ['שדיון נוסף אפשרי רק בעניינים פליליים', 'שדיון נוסף מתקיים תמיד בהרכב של חמישה בדיוק', 'שדיון נוסף יכול להפוך את התוצאה, ושדעת מיעוט בערעור עשויה להפוך לדעת הרוב', 'שבדיון נוסף לעולם מאשררים את התוצאה המקורית'], 'c': 2, 'e': 'נכון. בערעור הוחלט ברוב ארבעה מול אחד, ובדיון הנוסף בהרכב של אחד עשר התהפכה התוצאה, ושופט המיעוט בערעור היה ברוב.'}, {'q': 'העליון שוקל לבטל הלכה ותיקה שרבים הסתמכו עליה. איזה שיקול מדבר נגד הסטייה?', 'o': ['החקיקה סביב ההלכה השתנתה כך שהיא אינה משתלבת בה', 'אינטרס ההסתמכות והוודאות של מי שפעלו לפיה', 'חל שינוי חברתי מהותי מאז נפסקה', 'ההלכה התגלתה כבלתי ישימה'], 'c': 1, 'e': 'נכון. יציבות, הסתמכות ושוויון הם השיקולים המרכזיים נגד סטייה, ולכן גם נקבעים לעתים כללי מעבר.'}, {'q': 'מה מדגימה פרשת ליאור המר (2012) בהקשר של סטייה מהלכה?', 'o': ['שהעליון חייב לקבל אישור מהכנסת לשינוי הלכה', 'שהלכות בנזיקין אינן משתנות לעולם', 'שהעליון רשאי לבטל הלכה שלו ולקבוע כללי מעבר כדי להתחשב בהסתמכות', 'שערכאה נמוכה רשאית לבטל הלכה של העליון'], 'c': 2, 'e': 'נכון. העליון ביטל את עילת "חיים בעוולה" שהוכרה בזייצוב, הרחיב את עילת ההורים, ונקבעו כללי מעבר.'}, {'q': 'הכנסת תיקנה חוק כדי לבטל הלכה של העליון. בעל דין טוען שמעתה בית המשפט כבר אינו יכול לפרש את הנושא. מה מלמדת פרשת סהר?', 'o': ['התיקון חל רק אם אושר ברוב של 61 חברי כנסת', 'בית המשפט חייב לבקש חוות דעת מהכנסת על פירוש התיקון', 'בית המשפט ממשיך לפרש את החוק המתוקן, ואף עשוי לקבוע שהתיקון אימץ בפועל את הגישה הקודמת', 'הטענה נכונה — התיקון מבטל את כוחו הפרשני של בית המשפט'], 'c': 2, 'e': 'נכון. בסהר קבע הרוב שתיקון 2011 לס׳ 25(א) לחוק החוזים אימץ למעשה את גישת אפרופים, תוך הדגשת מקום הלשון.'}, {'q': 'מה קבע העליון בפרשת יששכרוב (2006), ומה זה מלמד על הלכה פסוקה?', 'o': ['שרק הכנסת רשאית לקבוע כללי פסילה', 'שאין במשפט הישראלי כל אפשרות לפסול ראיה שהושגה שלא כדין', 'שאומצה דוקטרינת פסילה פסיקתית — כלל שמקורו בהלכה ולא בחוק, והמחייב את כל הערכאות', 'שכל ראיה שהושגה שלא כדין נפסלת אוטומטית, כמו בדוקטרינת "פרי העץ המורעל"'], 'c': 2, 'e': 'נכון. זו דוגמה להלכה יוצרת: דוקטרינה שאינה כתובה בחוק ומחייבת מכוח ס׳ 20(ב).'}, {'q': 'מה קבעה "הלכת בן חיים" (2012)?', 'o': ['ששוטר רשאי לחפש בכל מקרה שהחשוד לא התנגד במפורש', 'שאסור לחפש בהסכמה בשום מקרה', 'שחיפוש בהסכמה מחייב תמיד צו שופט', 'שחיפוש בהסכמה, כשאין חשד סביר, כשר רק אם ההסכמה ניתנה מדעת — אחרי שהובהר שמותר לסרב'], 'c': 3, 'e': 'נכון. ההסכמה חייבת להיות מדעת, וזו מתגבשת רק אחרי שהשוטר הבהיר את הזכות לסרב ושלא יאונה רע למסרב.'}, {'q': 'מה ההבדל בין דיון נוסף למשפט חוזר?', 'o': ['אין הבדל — שני שמות לאותו הליך', 'דיון נוסף מתקיים במחוזי, ומשפט חוזר בעליון', 'דיון נוסף עוסק בבחינה מחודשת של הלכה שנפסקה בעליון בשלושה; משפט חוזר עוסק בתיקון עיוות דין בתיק פלילי שהוכרע סופית', 'דיון נוסף אפשרי רק בפלילים, ומשפט חוזר רק באזרחי'], 'c': 2, 'e': 'נכון. דיון נוסף נוגע להלכה (אזרחי ופלילי); משפט חוזר נוגע לתיק פלילי מסוים ולעיוות דין.'}, {'q': 'איזה משפט מתאר נכון את מעמדה של דעת מיעוט בפסק דין של העליון?', 'o': ['היא אינה מחייבת, אך עשויה להשפיע בעתיד — למשל בדיון נוסף או בחקיקה', 'היא מחייבת את הערכאות הנמוכות במקרים שבהם הרוב לא התייחס לשאלה', 'היא מבוטלת ואין לצטט אותה', 'היא מחייבת את העליון בתיקים הבאים'], 'c': 0, 'e': 'נכון. היא אינה מחייבת, אבל לעתים הופכת לרוב בעתיד, כפי שקרה בפרשת נחמני.'}, {'q': 'בפרשת ביבי כבישים כתב השופט שטיין, בהערת אגב, ש"לא כל החוזים נולדו שווים". שופט מחוזי שואל אם הוא מחויב לאמץ את ההבחנה. מה התשובה?', 'o': ['כן — כל מה שנכתב בפסק דין של העליון מחייב', 'כן — אם הערה צוטטה בפסקי דין אחרים היא הופכת למחייבת', 'לא, ואסור לו אפילו להתחשב בה', 'לא — זו אמרת אגב, שאינה מחייבת, אך רשאי להתחשב בה כטיעון משכנע'], 'c': 3, 'e': 'נכון. ההערה לא הייתה נחוצה להכרעה; היא בעלת משקל משכנע בלבד.'}, {'q': 'בדיון הנוסף בפרשת גיני (2017), מה נקבע לגבי בית אוכל שאין בידו תעודת הכשר?', 'o': ['שמותר לו להציג עצמו ככשר אם יש לו השגחה פרטית', 'שחוק איסור הונאה בכשרות בטל', 'שאסור לו להציג עצמו ככשר, אבל מותר לו להציג מצג אמת על הסטנדרטים ועל הפיקוח, תוך הבהרה שאין לו תעודת הכשר', 'שאסור לו למסור כל מידע על כשרות המזון'], 'c': 2, 'e': 'נכון. זו הכרעת הדיון הנוסף, בכפוף להבהרה המפורשת שאין לעסק תעודת הכשר.'}]
